import React from 'react';
import NavigationBar from './NavigationBar';
import Sidebar from './Sidebar';
import LMSDashboard from './LMSDashboard';

function App() {
  return (
    <div className="min-h-screen flex flex-col bg-gray-100">
      <NavigationBar />
      
      <div className="flex flex-1 pt-16">
        <Sidebar />
        
        <main className="flex-1 p-6 overflow-y-auto mb-16">
          <LMSDashboard />
        </main>
      </div>

      <footer className="fixed bottom-0 left-0 right-0 h-16 bg-slate-900 text-white flex items-center justify-center z-50 border-t border-slate-800">
        <p>&copy; 2026 LMS Private Tuition Center. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default App;
